import{_ as d,o as r,c as e,a5 as a}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"听力证据卡：从播放时长到意义重构","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/listening-audit.zh.md","filePath":"public/downloads/worksheets/listening-audit.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/listening-audit.zh.md"};function i(l,t,n,b,o,s){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="听力证据卡-从播放时长到意义重构" tabindex="-1">听力证据卡：从播放时长到意义重构 <a class="header-anchor" href="#听力证据卡-从播放时长到意义重构" aria-label="Permalink to &quot;听力证据卡：从播放时长到意义重构&quot;">​</a></h1><p>把这张卡复制到私有笔记中，一次只处理一份主材料与一份平行材料。不要记录密码、客户资料、未经许可的会议、学生或家庭录音；版权材料只在允许的个人学习范围内保存片段、转写和笔记。</p><h2 id="_1-定义任务与现实边界" tabindex="-1">1. 定义任务与现实边界 <a class="header-anchor" href="#_1-定义任务与现实边界" aria-label="Permalink to &quot;1. 定义任务与现实边界&quot;">​</a></h2><h3 id="listening-evidence-—-yyyy-mm-dd" tabindex="-1">Listening Evidence — YYYY-MM-DD <a class="header-anchor" href="#listening-evidence-—-yyyy-mm-dd" aria-label="Permalink to &quot;Listening Evidence — YYYY-MM-DD&quot;">​</a></h3><p>真实场景：<br> 任务：抓主旨 / 找细节 / 追踪关系 / 执行动作 / 进入互动 / 迁移<br> 听完以后需要回答、决定或做什么：<br> 完成标准：<br> 现实中允许的确认、字幕与书面辅助：<br> 录音、上传、转写和分享许可：</p><p>训练可以撤掉支架，真实工作不能为了证明能力而放弃必要的安全确认。</p><h2 id="_2-审计材料与条件" tabindex="-1">2. 审计材料与条件 <a class="header-anchor" href="#_2-审计材料与条件" aria-label="Permalink to &quot;2. 审计材料与条件&quot;">​</a></h2><p>主材料标题、来源与访问日期：<br> 平行材料标题、来源与访问日期：<br> 片段时长：<br> 可靠英文转写：人工 / 自动待核 / 无<br> 主题、说话者与口音熟悉度：<br> 设备 / 网络 / 房间噪声：<br> 版权与保存边界：<br> 我为什么愿意在七天内回来：</p><table tabindex="0"><thead><tr><th>条件</th><th>主材料</th><th>平行材料</th><th>是否可比较</th></tr></thead><tbody><tr><td>任务与难度</td><td></td><td></td><td></td></tr><tr><td>时长与信息密度</td><td></td><td></td><td></td></tr><tr><td>转写质量</td><td></td><td></td><td></td></tr><tr><td>说话者/口音熟悉度</td><td></td><td></td><td></td></tr><tr><td>设备与环境</td><td></td><td></td><td></td></tr></tbody></table><p>材料不同不等于迁移条件可比。至少保持任务和大致难度相近。</p><h2 id="_3-保存无字幕首听" tabindex="-1">3. 保存无字幕首听 <a class="header-anchor" href="#_3-保存无字幕首听" aria-label="Permalink to &quot;3. 保存无字幕首听&quot;">​</a></h2><p>首听允许：暂停 / 倍速 / 字幕 / 笔记 / 重播<br> 一句话主旨：<br> 三个确定细节：<br> 说话者态度或目的：<br> 关键数字 / 时间 / 人物 / 条件：<br> 不确定时间段：<br> 我根据所听会采取的行动：<br> 首听答案位置：</p><p>不要用第二遍或字幕后的答案覆盖首听。它是以后比较的基线。</p><h2 id="_4-建立六层错误地图" tabindex="-1">4. 建立六层错误地图 <a class="header-anchor" href="#_4-建立六层错误地图" aria-label="Permalink to &quot;4. 建立六层错误地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间段</th><th>我以为听到</th><th>可靠内容</th><th>障碍层</th><th>任务影响</th><th>本轮动作</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>技术环境 / 语言未知 / 已知未听出 / 结构指向 / 背景推断 / 注意力容量</td><td>意思改变 / 任务阻断 / 高频重复 / 理解费力 / 低影响</td><td></td></tr></tbody></table><p>最影响任务的一到三个问题：<br> 先不处理的低影响漏词：<br> 可能来自设备或疲劳、不能直接归因于能力的部分：</p><h2 id="_5-使用支架阶梯" tabindex="-1">5. 使用支架阶梯 <a class="header-anchor" href="#_5-使用支架阶梯" aria-label="Permalink to &quot;5. 使用支架阶梯&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>动作</th><th>我新看见了什么</th><th>仍然不能证明什么</th></tr></thead><tbody><tr><td>1</td><td>无字幕首听</td><td></td><td></td></tr><tr><td>2</td><td>只重听 5-20 秒问题片段</td><td></td><td></td></tr><tr><td>3</td><td>打开英文转写核对词界与结构</td><td></td><td></td></tr><tr><td>4</td><td>只查最小定义、背景或翻译</td><td></td><td></td></tr><tr><td>5</td><td>关闭文字按正常速度再听</td><td></td><td></td></tr><tr><td>6</td><td>三到七天后用平行材料撤架复测</td><td></td><td></td></tr></tbody></table><p>自动字幕错误：<br> 中文翻译帮助了什么：<br> 关闭文字后仍然触发的意思：<br> 只在字幕可见时才理解的片段：</p><h2 id="_6-让每一遍产生不同证据" tabindex="-1">6. 让每一遍产生不同证据 <a class="header-anchor" href="#_6-让每一遍产生不同证据" aria-label="Permalink to &quot;6. 让每一遍产生不同证据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>遍次</th><th>问题</th><th>输出</th><th>结果</th></tr></thead><tbody><tr><td>1</td><td>我预测什么，首听恢复什么？</td><td>原始主旨与细节</td><td></td></tr><tr><td>2</td><td>差异出现在哪个时间段？</td><td>时间戳与障碍层</td><td></td></tr><tr><td>3</td><td>最小支架解释了什么？</td><td>听错、原文与原因</td><td></td></tr><tr><td>4</td><td>关闭支架后声音是否独立触发意思？</td><td>无文字复听</td><td></td></tr><tr><td>5</td><td>我能怎样重构并行动？</td><td>复述 / 流程 / 决定 / 交接</td><td></td></tr></tbody></table><p>播放次数不是结果。每一遍都应留下新的判断，或证明不必继续重复。</p><h2 id="_7-从听写与跟读进入生成" tabindex="-1">7. 从听写与跟读进入生成 <a class="header-anchor" href="#_7-从听写与跟读进入生成" aria-label="Permalink to &quot;7. 从听写与跟读进入生成&quot;">​</a></h2><p>高影响 5-20 秒片段：<br> 我的听写：<br> 可靠转写：<br> 词界 / 词尾 / 弱读 / 重音差异：<br> 延迟跟读录音：<br> 三个关键词：<br> 合上文本后的复述：<br> 改变一个事实或立场后的说明：<br> 陌生追问与回答：</p><p>跟读顺畅而复述空白时，减少模仿长度，增加关键词重构；每个词都写对却说不出主旨时，回到结构和关系。</p><h2 id="_8-记录-ai、教师与真实任务反馈" tabindex="-1">8. 记录 AI、教师与真实任务反馈 <a class="header-anchor" href="#_8-记录-ai、教师与真实任务反馈" aria-label="Permalink to &quot;8. 记录 AI、教师与真实任务反馈&quot;">​</a></h2><p>工具 / 反馈者 / 模型版本与日期：<br> 它使用原始音频、自动转写还是我的候选转写：<br> 它提出的错误分类：<br> 它是否编造词语、背景或说话者意图：<br> 教师/同伴核验：<br> 真实任务中的回应、执行或修复结果：<br> 我采纳 / 拒绝什么，为什么：</p><p>AI 与自动转写可以提供候选，不是原音的最终裁判。</p><h2 id="_9-做延迟保持与迁移" tabindex="-1">9. 做延迟保持与迁移 <a class="header-anchor" href="#_9-做延迟保持与迁移" aria-label="Permalink to &quot;9. 做延迟保持与迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>撤掉什么</th><th>改变的条件</th><th>输出</th><th>结果</th></tr></thead><tbody><tr><td>第 1 天</td><td>不使用完整字幕</td><td>主材料</td><td>首听与意义重构</td><td></td></tr><tr><td>第 3-7 天</td><td>撤掉旧笔记与转写</td><td>平行材料</td><td>主旨、细节、行动</td><td></td></tr><tr><td>第 14 天</td><td>撤掉最近反馈</td><td>新说话者、口音或设备</td><td>复述 + 陌生追问</td><td></td></tr><tr><td>第 30 天</td><td>关闭全部练习提示</td><td>真实会议、课程或对话</td><td>完整任务</td><td></td></tr></tbody></table><p>七天后仍能使用的方法：<br> 换材料后再次出现的障碍：<br> 是否更少依赖全文字幕或翻译：<br> 是否更能请求重复、确认并留下共识：<br> 下一轮只改变的变量：</p><h2 id="_10-评分与去留" tabindex="-1">10. 评分与去留 <a class="header-anchor" href="#_10-评分与去留" aria-label="Permalink to &quot;10. 评分与去留&quot;">​</a></h2><p>每项 0-2：<code>0=未完成</code>，<code>1=依赖提示或不稳定</code>，<code>2=当前条件下完成</code>。</p><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">第 1 天</th><th style="text-align:right;">第 7 天</th><th style="text-align:right;">第 14 天</th><th>证据理由</th></tr></thead><tbody><tr><td>首听保留主线</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>恢复关键细节与关系</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能定位障碍层</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>关闭字幕后仍能理解</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能重构、回应或执行</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>换材料、说话者或设备后仍能完成</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>当前证据支持：继续主材料 / 降级为泛听 / 更换材料 / 转向另一问题<br> 最重要的依据：<br> 仍不能推出的结论：<br> 下一项最小任务：<br> 下一次复查日期：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-1/3-listening" target="_blank" rel="noreferrer">听力篇：从声音辨认到真实理解</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/5-speaking" target="_blank" rel="noreferrer">口语篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/7-ai" target="_blank" rel="noreferrer">用 AI 学英语</a> ｜ <a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/listening-audit" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-02。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',38)])])}const c=d(h,[["render",i]]);export{p as __pageData,c as default};
